/* Load all 24 sprite tiles for a character into sprite VRAM. */
void player_sprites_load_char(UINT8 idx) NONBANKED {
    UINT8 old_bank = _current_bank;
    if (idx >= 16u) idx = 0;
    SWITCH_ROM_MBC1(10);
    set_sprite_data(0, 24u, all_sprite_data + (UINT16)idx * 384u);
    SWITCH_ROM_MBC1(old_bank);
}

/* Load DOWN standing preview (4 tiles) as BG tiles at index 128. */
void player_sprites_load_preview(UINT8 idx) NONBANKED {
    UINT8 old_bank = _current_bank;
    if (idx >= 16u) idx = 0;
    SWITCH_ROM_MBC1(10);
    set_bkg_data(128u, 4u, all_sprite_data + (UINT16)idx * 384u);
    SWITCH_ROM_MBC1(old_bank);
}

void player_sprites_load(void) NONBANKED {
    player_sprites_load_char(0);
}
